import { readFileSync } from "node:fs";

import { describe, expect, it } from "vitest";

import { whisperFeatures } from "../src/features";

function floats(name: string): Float32Array {
  const bytes = readFileSync(new URL(`./fixtures/${name}`, import.meta.url));
  return new Float32Array(bytes.buffer, bytes.byteOffset, bytes.length / 4);
}

describe("Whisper features", () => {
  it("match Hugging Face's WhisperFeatureExtractor", () => {
    // Generated by WhisperFeatureExtractor(chunk_length=1) with do_normalize=True from one
    // second of a chirp with a DC offset, so the reflected edges and normalization count.
    const expected = floats("chirp-whisper-features.f32");
    const actual = whisperFeatures(floats("chirp.f32"));
    let maxError = 0;
    for (let mel = 0; mel < 80; mel++) {
      for (let frame = 0; frame < 100; frame++) {
        const error = Math.abs(
          (actual[mel * 100 + frame] ?? 0) - (expected[mel * 100 + frame] ?? 0),
        );
        maxError = Math.max(maxError, error);
      }
    }
    expect(maxError).toBeLessThan(1e-4);
  });

  it("makes 80 mel bins per 10 ms of audio", () => {
    expect(whisperFeatures(new Float32Array(128000))).toHaveLength(80 * 800);
  });

  it("floors silence to a constant", () => {
    expect(new Set(whisperFeatures(new Float32Array(16000)))).toEqual(new Set([-1.5]));
  });

  it("puts a tone's energy in the mel bin of its frequency", () => {
    const tone = Float32Array.from({ length: 16000 }, (_, index) =>
      Math.sin((2 * Math.PI * 1000 * index) / 16000),
    );
    const features = whisperFeatures(tone);
    const frame = 50;
    const column = Array.from({ length: 80 }, (_, mel) => features[mel * 100 + frame] ?? 0);
    const loudest = column.indexOf(Math.max(...column));
    // 1 kHz is 15 on the Slaney scale, which tops out at 45.3 for 8 kHz: bin 15 / 45.3 * 81 - 1.
    expect(loudest).toBe(26);
  });
});
